"""Deploy trained adapters for serving via the AutoSLM control plane.

Training runs on AutoSLM stream their LoRA adapters to the operator's
HuggingFace artifact store as they train, so there is no separate
"upload checkpoint" step anymore: deployment is one call keyed by the
AutoSLM run id recorded on the platform run
(``config["autoslm_run_id"]`` / ``<log_dir>/autoslm_run_<phase>.json``).

The control plane is the fixed hosted endpoint; these helpers talk to it over
plain HTTP (no autoslm package dependency).
"""

from __future__ import annotations

from typing import Any

from freesolo.utils.core import require_non_empty

DEPLOY_MODES = ("dev", "always-on")


def _client():
    try:
        from freesolo.training.autoslm import autoslm_client
    except ModuleNotFoundError as exc:
        raise RuntimeError(
            "freesolo.training package is not part of this SDK build"
        ) from exc
    except Exception as exc:
        raise RuntimeError(
            "freesolo.training autoslm client failed to initialize"
        ) from exc

    return autoslm_client()


def deploy_lora_adapter(
    run_id: str,
    *,
    mode: str = "dev",
    idle_timeout: int | None = None,
) -> dict[str, Any]:
    """Deploy a trained run's adapter for OpenAI-style chat serving.

    ``mode="dev"`` is scale-to-zero ($0 idle, cold starts after inactivity);
    ``mode="always-on"`` keeps one warm worker with continuous billing.
    """
    cleaned_run_id = require_non_empty(run_id, "run_id")
    if mode not in DEPLOY_MODES:
        raise ValueError(f"mode must be one of {', '.join(DEPLOY_MODES)}; got {mode!r}")
    kwargs: dict[str, Any] = {"mode": mode}
    if idle_timeout is not None:
        kwargs["idle_timeout_s"] = int(idle_timeout)
    return _client().deploy(cleaned_run_id, **kwargs)


def undeploy_lora_adapter(run_id: str) -> dict[str, Any]:
    """Tear down a run's serving endpoint."""
    return _client().undeploy(require_non_empty(run_id, "run_id"))


def get_run_status(run_id: str) -> dict[str, Any]:
    """Fetch an AutoSLM run's status (state, cost, deployment)."""
    return _client().get_run(require_non_empty(run_id, "run_id"))


def list_deployments() -> list[dict[str, Any]]:
    """List the account's active serving deployments."""
    return list(_client().deployments())


__all__ = [
    "DEPLOY_MODES",
    "deploy_lora_adapter",
    "get_run_status",
    "list_deployments",
    "undeploy_lora_adapter",
]
